def compute_Last_Digit(a, b):
    if b < a:
        raise ValueError("b must be greater than or equal to a")
    if a == b:
        return 1
    # The quotient b!/a! = product of integers from a+1 to b
    # Compute product mod 10 to get last digit
    result = 1
    for x in range(a + 1, b + 1):
        result = (result * (x % 10)) % 10
        if result == 0:
            # Once zero, remains zero
            break
    return result
