def remove_column(data, target):
    if isinstance(data, dict):
        # Remove the key from the dict if present
        if target in data:
            new_dict = data.copy()
            del new_dict[target]
            return new_dict
        else:
            # Recursively process nested dict/list values
            changed = False
            new_dict = {}
            for k, v in data.items():
                nv = remove_column(v, target)
                if nv is not v:
                    changed = True
                new_dict[k] = nv
            return new_dict if changed else data
    elif isinstance(data, list):
        # If target is a valid index, remove it
        if isinstance(target, int) and 0 <= target < len(data):
            return data[:target] + data[target+1:]
        else:
            # Recursively process elements in the list
            changed = False
            new_list = []
            for item in data:
                nv = remove_column(item, target)
                if nv is not item:
                    changed = True
                new_list.append(nv)
            return new_list if changed else data
    else:
        return data
