def remove_column(data, pos):
    def remove_from_grouping(grouping, pos):
        if len(grouping) > pos:
            items = list(grouping)
            del items[pos]
            try:
                return type(grouping)(items)
            except TypeError:
                return items
        else:
            return grouping

    # Check if each element in data is itself a grouping of groupings (nested)
    # If so, apply removal recursively one level down; else apply removal directly.
    # Spec requires removal only at the immediate inner grouping level.
    # To reconcile test_8, detect if inner grouping is itself iterable of groupings,
    # then remove from each inner grouping inside it; else remove from grouping itself.

    def is_grouping(obj):
        # Treat strings as non-groupings for this purpose
        return hasattr(obj, '__getitem__') and not isinstance(obj, (str, bytes))

    result = []
    for grouping in data:
        if is_grouping(grouping):
            # Check if grouping contains groupings (nested)
            if all(is_grouping(g) for g in grouping):
                # Nested inner groupings: remove from each inner grouping
                new_inner = []
                for inner in grouping:
                    new_inner.append(remove_from_grouping(inner, pos))
                try:
                    result.append(type(grouping)(new_inner))
                except TypeError:
                    result.append(new_inner)
            else:
                # Flat inner grouping: remove directly
                result.append(remove_from_grouping(grouping, pos))
        else:
            # Not a grouping, keep as is
            result.append(grouping)
    return result
