        if isinstance(l, list):
            return (False, sum(l))
        else:
            return (False, l)

    def strictly_increasing(seq):
        return all(x < y for x, y in zip(seq, seq[1:]))

    def strictly_decreasing(seq):
        return all(x > y for x, y in zip(seq, seq[1:]))

    is_mono = strictly_increasing(l) or strictly_decreasing(l)

    if isinstance(l, list):
        return (is_mono, sum(l))
    else:
        return (is_mono, l)
