def find_solution(a: int, b: int, n: int):
    # Handle trivial cases
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return None

    # Extended Euclidean Algorithm to find gcd and one solution (x0, y0)
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (g, x, y)

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        return None  # No integer solutions

    # Scale initial solution to n
    x0 *= n // g
    y0 *= n // g

    # Adjust signs according to a and b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # If either a or b is zero, handle separately
    if a == 0:
        # equation: b*y = n
        if b == 0:
            return None  # already handled above, but safe here
        if n % b != 0:
            return None
        y = n // b
        if y < 0:
            return None
        return (0, y)
    if b == 0:
        # equation: a*x = n
        if n % a != 0:
            return None
        x = n // a
        if x < 0:
            return None
        return (x, 0)

    # General case a != 0 and b != 0
    # General solution:
    # x = x0 + k*(b/g)
    # y = y0 - k*(a/g)
    # We want x,y >= 0 and minimal x >= 0

    # Step size
    b_div = b // g
    a_div = a // g

    # Find range of k for which x and y are non-negative
    # x >= 0 => x0 + k*b_div >= 0 => k >= ceil(-x0/b_div)
    # y >= 0 => y0 - k*a_div >= 0 => k <= floor(y0/a_div)

    # Because b_div and a_div may be negative, compute bounds carefully
    import math

    def ceildiv(a, b):
        return -((-a) // b) if b else 0

    # Compute lower bound for k (x >= 0)
    if b_div > 0:
        k_min = ( -x0 + b_div - 1 ) // b_div
    elif b_div < 0:
        k_min = ( -x0 ) // b_div  # since b_div negative, division rounds down
    else:
        # b_div == 0 means infinite solutions in k for x, but b_div=0 only if b=0 handled above
        k_min = -10**18  # effectively no lower bound

    # Compute upper bound for k (y >= 0)
    if a_div > 0:
        k_max = y0 // a_div
    elif a_div < 0:
        k_max = ( y0 + (-a_div) - 1 ) // (-a_div)  # careful with negative division
        k_max = (y0) // a_div  # since a_div < 0, floor division is safe
    else:
        k_max = 10**18  # effectively no upper bound if a_div=0, but a_div=0 only if a=0 handled above

    # Because signs can be tricky, recompute k_min, k_max with safe math:

    # Safer bounds:
    # x >= 0 => k >= ceil(-x0 / b_div) if b_div != 0
    # y >= 0 => k <= floor(y0 / a_div) if a_div != 0

    def safe_ceil_div(numer, denom):
        if denom == 0:
            return None
        q, r = divmod(numer, denom)
        if r == 0:
            return q
        if (denom > 0 and r > 0) or (denom < 0 and r < 0):
            return q + 1
        else:
            return q

    def safe_floor_div(numer, denom):
        if denom == 0:
            return None
        q, r = divmod(numer, denom)
        if r == 0:
            return q
        if (denom > 0 and r > 0) or (denom < 0 and r < 0):
            return q
        else:
            return q - 1

    k_min = safe_ceil_div(-x0, b_div)
    k_max = safe_floor_div(y0, a_div)

    if k_min is None:
        k_min = -10**18
    if k_max is None:
        k_max = 10**18

    if k_min > k_max:
        return None  # no k satisfies both inequalities

    # Among all valid k in [k_min, k_max], minimal x corresponds to minimal k
    # Because x = x0 + k*b_div, and b_div > 0 => minimal x at k_min
    # If b_div < 0, minimal x at k_max

    if b_div > 0:
        k = k_min
    elif b_div < 0:
        k = k_max
    else:
