def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 0:
        return 0
    # dp[i][x]: number of sequences of length i ending with element x
    dp = [1] * (m + 1)  # sequences of length 1: dp[x] = 1 for x in [1..m], index 0 unused
    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # prefix sums for dp to optimize sum queries
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[x]
        for x in range(1, m + 1):
            # previous element y must satisfy: x >= 2 * y => y <= x // 2
            max_prev = x // 2
            if max_prev >= 1:
                new_dp[x] = prefix[max_prev]
            else:
                new_dp[x] = 0
        dp = new_dp
    return sum(dp[1:])
```

