def dif_Square(value: int) -> bool:
    n = value
    if n == 0:
        return True
    abs_n = abs(n)
    # Find divisors without imports
    divisors = []
    i = 1
    while i * i <= abs_n:
        if abs_n % i == 0:
            divisors.append(i)
            if i * i != abs_n:
                divisors.append(abs_n // i)
        i += 1
    for d in divisors:
        d1, d2 = d, n // d if d != 0 else 0
        # Check sign combinations that yield n = x * y
        candidates = []
        if n > 0:
            candidates.append((d1, d2))
            candidates.append((-d1, -d2))
        else:
            candidates.append((d1, -d2))
            candidates.append((-d1, d2))
        for x, y in candidates:
            # Check if (x+y) and (x-y) are both even
            if (x + y) % 2 == 0 and (x - y) % 2 == 0:
                # Then a,b = (x+y)//2, (x-y)//2 are integers
                return True
    return False
```

