def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)
    if set(s) == {'9'}:
        # All 9's case: next palindrome is 100...001
        return num + 2  # e.g. 9 -> 11, 99 -> 101, 999 -> 1001

    def make_palindrome(left: str, middle: str, odd_len: bool) -> int:
        if odd_len:
            return int(left + middle + left[::-1])
        else:
            return int(left + left[::-1])

    odd_len = (length % 2 != 0)
    if odd_len:
        left = s[:length // 2]
        middle = s[length // 2]
        right = s[length // 2 + 1:]
    else:
        left = s[:length // 2]
        middle = ''
        right = s[length // 2:]

    # First try: mirror the left to right to form palindrome
    candidate = make_palindrome(left, middle, odd_len)
    if candidate > num:
        return candidate

    # Need to increment the middle part and then mirror again
    if odd_len:
        # Increment the middle digit and handle carry
        mid_num = int(left + middle)
        mid_num += 1
        mid_str = str(mid_num)
        if len(mid_str) > len(left + middle):
            # Carry overflow, length increased
            # For example 999 -> 1000, palindrome length increases
            return int('1' + ('0' * (length - 1)) + '1')
        new_left = mid_str[:-1]
        new_middle = mid_str[-1]
        return make_palindrome(new_left, new_middle, odd_len)
    else:
        # Even length: increment the left half and mirror
        left_num = int(left)
        left_num += 1
        left_str = str(left_num)
        if len(left_str) > len(left):
            # Carry overflow, length increased
            # For example 99 -> 100, so next palindrome is 101
            return int('1' + ('0' * (length - 1)) + '1')
        return make_palindrome(left_str, '', odd_len)
```

