def find_solution(a: int, b: int, n: int) -> tuple[int, int]:
    if a == 0 and b == 0:
        # Infinite or no solutions, spec does not require handling
        # Return (0,0) as a placeholder (not specified)
        return (0, 0)
    if a == 0:
        # Equation: b*y = n, x=0 first candidate
        if b != 0 and n % b == 0:
            return (0, n // b)
        else:
            # No solution if b=0 or n%b!=0, behavior unspecified
            # Return something consistent with scanning from x=0
            return (0, 0)
    if b == 0:
        # Equation: a*x = n, y arbitrary (choose y=0)
        if a != 0 and n % a == 0:
            return (n // a, 0)
        else:
            # No solution if a=0 or n%a!=0, behavior unspecified
            # Return something consistent scanning from x=0
            return (0, 0)
    # b != 0 and a != 0: scan x from 0 upward
    x = 0
    while True:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            return (x, y)
        x += 1
```

