def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 1:
        return m
    dp = [1] * (m + 1)  # dp[x]: count of sequences of length 1 ending with x (1..m)
    for length in range(2, n + 1):
        prefix_sum = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix_sum[x] = prefix_sum[x - 1] + dp[x]
        new_dp = [0] * (m + 1)
        for x in range(1, m + 1):
            min_prev = (x + 1) // 2  # smallest previous element <= x/2, so prev <= x/2 means prev < min_prev
            if min_prev - 1 >= 1:
                new_dp[x] = prefix_sum[min_prev - 1]
            # else new_dp[x] stays 0
        dp = new_dp
    return sum(dp[1:])
