def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # If all digits are '9', the next palindrome is 10...01 (length+1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    half_len = (length + 1) // 2
    left_half = s[:half_len]
    odd_length = (length % 2 != 0)

    # First palindrome by mirroring left_half
    palindrome = make_palindrome(left_half, odd_length)
    if palindrome > n:
        return palindrome

    # Increment left_half and mirror again
    left_num = int(left_half) + 1
    left_half_str = str(left_num)

    # If increment changes the length of left_half, means length increased
    if len(left_half_str) > len(left_half):
        # This happens when all digits in left_half are 9, e.g. 999 -> 1000
        # Next palindrome length increased by 1
        # For example, 999 -> 1001, or 9999 -> 10001
        return int('1' + ('0' * (length - 1)) + '1')

    palindrome = make_palindrome(left_half_str, odd_length)
    return palindrome
