def find_solution(a, b, n):
    from math import gcd

    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (g, x, y)

    # Handle trivial case
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return None

    g = gcd(a, b)
    if n % g != 0:
        return None

    # Scale down
    a1, b1, n1 = a // g, b // g, n // g

    # Extended Euclidean to find one solution
    g, x0, y0 = extended_gcd(a1, b1)
    x0 *= n1
    y0 *= n1

    # If a and b are zero handled above, so now a1 and b1 not both zero.

    # If a1 == 0:
    if a1 == 0:
        # Equation: b1*y = n1
        if b1 == 0:
            # a1=0,b1=0 handled above
            return None
        if n1 % b1 != 0:
            return None
        y = n1 // b1
        if y < 0:
            return None
        return (0, y)

    # If b1 == 0:
    if b1 == 0:
        # Equation: a1*x = n1
        if n1 % a1 != 0:
            return None
        x = n1 // a1
        if x < 0:
            return None
        return (x, 0)

    # General case: all a1,b1,n1 nonzero or zero but not both zero

    # Solutions are x = x0 + k*(b1), y = y0 - k*(a1), for any integer k

    # We want to find k such that x >=0 and y >=0

    # x >= 0 => x0 + k*b1 >= 0 => k >= -x0 / b1
    # y >= 0 => y0 - k*a1 >= 0 => k <= y0 / a1

    # Because a1,b1 can be negative, handle sign carefully:
    def div_ceil(a, b):
        # ceil(a/b) with integer division
        if b == 0:
            return None
        if b > 0:
            return (a + b - 1) // b
        else:
            return (a + b + 1) // b

    def div_floor(a, b):
        # floor(a/b) with integer division
        if b == 0:
            return None
        if b > 0:
            return a // b
        else:
            return a // b

    # Compute bounds for k

    # For x >= 0:
    if b1 != 0:
        if b1 > 0:
            k_min = (-x0 + b1 - 1) // b1  # ceil(-x0/b1)
        else:
            k_min = (-x0 + b1 + 1) // b1  # ceil(-x0/b1)
    else:
        # b1==0, x = x0 constant, check if x0 >=0
        if x0 < 0:
            return None
        else:
            k_min = -10**18  # effectively no constraint

    # For y >= 0:
    if a1 != 0:
        if a1 > 0:
            k_max = y0 // a1  # floor(y0/a1)
        else:
            k_max = y0 // a1  # floor(y0/a1)
    else:
        if y0 < 0:
            return None
        else:
            k_max = 10**18  # effectively no constraint

    # Because a1,b1 can be negative, let's recompute carefully:

    # Use div_ceil and div_floor functions to be precise:

    if b1 != 0:
        k_min = div_ceil(-x0, b1)
    else:
        if x0 < 0:
            return None
        k_min = -10**18

    if a1 != 0:
        k_max = div_floor(y0, a1)
    else:
        if y0 < 0:
            return None
        k_max = 10**18

    if k_min > k_max:
        # no k satisfies non-negative x,y
        return None

    # Choose any k in [k_min, k_max], for example k = k_min
    k = k_min

    x = x0 + k * b1
    y = y0 - k * a1

    if x < 0 or y < 0:
        # Defensive check, should not happen
        return None

    return (x, y)
```

