def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # If all 9's, next palindrome is 10..01 (1 followed by zeros and ending with 1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd = (length % 2 != 0)
    mid = length // 2

    if odd:
        left = s[:mid+1]
    else:
        left = s[:mid]

    palindrome = make_palindrome(left, odd)

    if palindrome > n:
        return palindrome

    # Increment the middle part and create palindrome again
    # Convert left part to int and add 1
    left_num = int(left)
    left_num += 1
    left = str(left_num)

    # If length increased after increment (e.g. 99 + 1 = 100)
    if len(left) > (mid + 1 if odd else mid):
        # This means the palindrome length increases by 1 or more
        # New palindrome is '1' + zeros + '1' with length +1 or length+1 odd/even adjustment
        return int('1' + ('0' * (length - 1)) + '1')

    return make_palindrome(left, odd)
```

