def find_solution(a: int, b: int, n: int) -> tuple[int, int]:
    def extended_gcd(x: int, y: int) -> tuple[int, int, int]:
        if y == 0:
            return (x, 1, 0)
        gcd, x1, y1 = extended_gcd(y, x % y)
        return (gcd, y1, x1 - (x // y) * y1)

    # Handle the case a = b = 0 separately
    if a == 0 and b == 0:
        if n == 0:
            # Infinite solutions; return any (0,0)
            return (0, 0)
        else:
            # No solution
            raise ValueError("No solution exists")

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        # No solution exists
        raise ValueError("No solution exists")

    # Scale the solution
    x0 *= n // gcd
    y0 *= n // gcd

    # Adjust signs to match original a and b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return (x0, y0)
```

