            else:
                # sum dp[start..m]
                # To do this efficiently, we use suffix sums
                # We'll build suffix sums for dp once per iteration
                # But here, we do inside the loop to avoid extra storage
                # So instead, we build suffix sums outside this loop
                pass
        # Build suffix sums of dp to allow O(1) range sums
        suffix_sums = [0] * (m + 2)
        for i in range(m, 0, -1):
            suffix_sums[i] = suffix_sums[i + 1] + dp[i]
        for val in range(1, m + 1):
