def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)
    if all(ch == '9' for ch in s):
        # If all digits are '9', next palindrome is 10...01 with length+1
        return int('1' + ('0' * (length - 1)) + '1')

    half_len = (length + 1) // 2
    left_half = s[:half_len]
    # Construct palindrome by mirroring left_half to right
    if length % 2 == 0:
        pal = left_half + left_half[::-1]
    else:
        pal = left_half + left_half[:-1][::-1]

    if int(pal) > n:
        return int(pal)

    # Increment the left half and form palindrome again
    left_num = int(left_half) + 1
    left_str = str(left_num)
    # If increment changes length (e.g., 99->100), adjust palindrome size
    if len(left_str) > len(left_half):
        if length % 2 == 0:
            # Even length case: new palindrome length increases by 1
            return int(left_str + left_str[:-1][::-1])
        else:
            # Odd length case: new palindrome length increases by 1
            return int(left_str + left_str[:-1][::-1])
    else:
        if length % 2 == 0:
            return int(left_str + left_str[::-1])
        else:
            return int(left_str + left_str[:-1][::-1])
