def find_solution(a: int, b: int, n: int) -> tuple[int, int]:
    if b == 0:
        # Then equation is a*x = n, y can be any integer
        # So solution exists only if n divisible by a and x >=0
        if a == 0:
            if n == 0:
                return 0, 0  # 0*0 + 0*0 = 0
            else:
                raise ValueError("No solution")
        if n % a == 0 and n // a >= 0:
            return n // a, 0
        else:
            raise ValueError("No solution")
    if a == 0:
        # Equation 0*x + b*y = n => b*y = n
        # x must be >= 0; since a=0, x=0 only
        if n % b == 0:
            return 0, n // b
        else:
            raise ValueError("No solution")
    abs_b = abs(b)
    x = 0
    while True:
        remainder = n - a * x
        if remainder % abs_b == 0:
            y = remainder // b
            return x, y
        x += 1
