import math

def highest_Power_of_2(base, value):
    if base == 0:
        if value == 0:
            return 1  # 0**1 == 0; exponent can be any positive number, choose 1
        elif value == 1:
            return 0  # 0**0 is conventionally 1
        else:
            raise ValueError("No exponent satisfies 0**exponent == value for value != 0 or 1")
    if base == 1:
        if value == 1:
            return 0  # 1**e == 1 for any e; return 0 as simplest exponent
        else:
            raise ValueError("No exponent satisfies 1**exponent == value for value != 1")
    if base == -1:
        if value == 1:
            return 0  # (-1)**0 == 1
        elif value == -1:
            return 1  # (-1)**1 == -1
        else:
            raise ValueError("No integer exponent satisfies (-1)**exponent == value other than ±1")
    if base < 0:
        if value == 0:
            # negative base to any positive integer power can't be zero; no solution
            raise ValueError("No exponent satisfies negative base to zero value")
        abs_base = abs(base)
        abs_value = abs(value)
        if abs_base == 0:
            if value == 0:
                return 1
            else:
                raise ValueError("No exponent satisfies 0**exponent == value")
        try:
            exponent = math.log(abs_value) / math.log(abs_base)
        except ValueError:
            raise ValueError("Math domain error in logarithm")
        if abs(round(exponent) - exponent) > 1e-12:
            raise ValueError("Exponent not integer for negative base input")
        exponent = round(exponent)
        # Check sign consistency
        if (exponent % 2 == 0 and value < 0) or (exponent % 2 == 1 and value > 0):
            raise ValueError("No real exponent with negative base matches value sign")
        return exponent
    # base > 0 and base != 1
    if value == 0:
        # For positive base, base**exponent == 0 only as exponent -> -inf, no finite exponent
        raise ValueError("No finite exponent satisfies base**exponent == 0 for base > 0")
    try:
        exponent = math.log(value) / math.log(base)
    except ValueError:
        raise ValueError("Math domain error in logarithm")
    # Round if very close to integer (to avoid floating point rounding issues)
    r = round(exponent)
    if abs(exponent - r) < 1e-12:
        return r
    return exponent
```

