def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)
    # Handle single digit numbers quickly
    if n < 8:
        return n + 1
    # Check if all digits are '9'
    if all(ch == '9' for ch in s):
        # Next palindrome is 10...01 with length+1
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd = (length % 2 != 0)
    mid = length // 2
    if odd:
        left = s[:mid + 1]
    else:
        left = s[:mid]

    pal = make_palindrome(left, odd)
    if pal > n:
        return pal

    # Increment the left part and rebuild palindrome
    left_num = int(left)
    left_num += 1
    left = str(left_num)
    # If increment causes length change (like 999 -> 1000)
    if len(left) > len(s[:mid + (1 if odd else 0)]):
        # This means the palindrome length increases, so return 10...01 of length+1
        return int('1' + ('0' * (length - 1)) + '1')
    return make_palindrome(left, odd)
