def find_solution(a: int, b: int, n: int) -> tuple[int, int]:
    def extended_gcd(aa: int, bb: int):
        if bb == 0:
            return (aa, 1, 0)
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        # No solution exists; problem does not specify what to do.
        # Returning None or raising is disallowed by spec; 
        # but spec does not say no solution possible inputs.
        # Let's raise an error as no solution exists.
        raise ValueError("No integer solutions")
    x0 *= n // g
    y0 *= n // g

    a_div = a // g
    b_div = b // g

    # x = x0 + k*(b/g), y = y0 - k*(a/g)
    # We want x >= 0,
    # so x0 + k*b_div >= 0 => k >= -x0 / b_div if b_div > 0 else k <= -x0 / b_div

    # Because k is integer, we find the smallest k so that x >= 0

    if b_div > 0:
        k_min = (-x0 + b_div - 1) // b_div  # ceil division for negative numerator
    else:
        k_min = (-x0) // b_div  # floor division since b_div < 0

    x = x0 + k_min * b_div
    y = y0 - k_min * a_div

    return (x, y)
```

