def find_exponentio(base: float, exp: float) -> float:
    import math

    if base == 0.0:
        if exp == 0.0:
            return 1.0  # 0**0 by convention
        elif exp > 0.0:
            return 0.0
        else:
            raise ZeroDivisionError("0 cannot be raised to a negative power")

    if base < 0.0:
        # Check if exp is integer (int or float integral)
        if isinstance(exp, int) or (isinstance(exp, float) and exp.is_integer()):
            int_exp = int(exp)
            result = pow(abs(base), int_exp)
            if int_exp % 2 == 1:
                return -result
            else:
                return result
        else:
            # Fractional exponent with negative base: raise ValueError
            raise ValueError("Negative base with fractional exponent results in complex number")

    return pow(base, exp)
