def get_total_number_of_sequences(N: int, K: int) -> int:
    if K == 1:
        return N if N >= 1 else 0
    if N < 1 or K < 1:
        return 0

    dp = [0] * (N + 1)
    for x in range(1, N + 1):
        dp[x] = 1

    for _ in range(2, K + 1):
        prefix_sum = [0] * (N + 2)
        for x in range(1, N + 1):
            prefix_sum[x] = prefix_sum[x - 1] + dp[x]
        new_dp = [0] * (N + 1)
        for x in range(1, N + 1):
            limit = x // 2
            if limit >= 1:
                new_dp[x] = prefix_sum[limit]
            else:
                new_dp[x] = 0
        dp = new_dp

    return sum(dp)
```

