def find_Max(sequence):
    if not sequence:
        raise ValueError("Empty sequence is not a valid rotated sorted sequence")
    low, high = 0, len(sequence) - 1
    while low < high:
        mid = (low + high) // 2
        if sequence[mid] > sequence[high]:
            low = mid + 1
        else:
            high = mid
    # low is index of minimum element; max is element before it (mod length)
    return sequence[low - 1]
