def next_smallest_palindrome(number):
    # Only integer inputs considered as per spec and tests.
    n = number
    if n <= 0:
        # No smaller palindrome less than 0 or 1 in positive domain, return type matched 0 or less.
        return type(number)(0)
    s = str(n)
    length = len(s)

    # Helper to check palindrome
    def is_palindrome(x):
        sx = str(x)
        return sx == sx[::-1]

    # If number <= 10, the next smallest palindrome strictly less is number-1 (if > 0)
    if n <= 10:
        cand = n - 1
        if cand < 0:
            return type(number)(0)
        return type(number)(cand)

    # Generate palindrome by mirroring left to right
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 != 0)
    half_len = (length + 1) // 2 if odd_length else length // 2
    left = s[:half_len]

    # Construct palindrome candidate from left half
    pal_str = make_palindrome(left, odd_length)
    pal_num = int(pal_str)

    if pal_num >= n:
        # Need to decrement the left half and then build palindrome again
        left_num = int(left)
        left_num -= 1
        left_str = str(left_num)
        # Handle the case where length of left_str < half_len after decrement (e.g. 1000 -> 0999)
        if len(left_str) < half_len:
            # This means the palindrome with current length is not feasible,
            # so the answer is all 9's of length-1 (e.g. 1000 -> 999)
            return type(number)(int('9' * (length - 1)))
        pal_str = make_palindrome(left_str, odd_length)
        pal_num = int(pal_str)

    if pal_num < n:
        return type(number)(pal_num)
    else:
        # If still not less (very rare), fallback to all 9's of length-1
        return type(number)(int('9' * (length - 1)))
```

