def find_solution(a: int, b: int, n: int):
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = extended_gcd(y, x % y)
        return (g, t, s - (x // y) * t)

    # Handle the trivial no-solution case
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        return None

    x0 *= n // g
    y0 *= n // g

    # Adjust signs according to original a and b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return (x0, y0)
