def get_total_number_of_sequences(n: int, m: int) -> int:
    if n <= 0 or m <= 0:
        return 0
    if n == 1:
        return m

    # dp[i][x] = number of sequences of length i starting with x
    # For convenience, store only current and next dp arrays.
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1  # base case: sequences of length 1 starting with x

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # Precompute prefix sums for dp for efficient range sum queries
        prefix_sum = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix_sum[x] = prefix_sum[x - 1] + dp[x]

        for x in range(1, m + 1):
            min_next = 2 * x
            if min_next <= m:
                # sum dp[y] for y in [min_next..m] = prefix_sum[m] - prefix_sum[min_next - 1]
                new_dp[x] = prefix_sum[m] - prefix_sum[min_next - 1]
            else:
                new_dp[x] = 0
        dp = new_dp

    return sum(dp[1:])
```

