def parse_nested_parens(paren_string: str) -> List[int]:
    def group_value(group: str) -> int:
        max_depth = 0
        depth = 0
        for c in group:
            if c == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif c == ')':
                depth -= 1
                if depth < 0:
                    # Unbalanced parentheses; could raise or ignore per spec
                    raise ValueError("Unbalanced parentheses")
            else:
                # Invalid character in group
                raise ValueError("Invalid character in input")
        if depth != 0:
            raise ValueError("Unbalanced parentheses at end of group")
        return max_depth

    if not paren_string.strip():
        return []

    groups = paren_string.split(' ')
    # According to spec, only single spaces separate groups; multiple spaces or empty groups may raise error
    # But spec allows exception or partial output; we handle empty groups by raising exception
    result = []
    for g in groups:
        if not g:
            raise ValueError("Empty group found due to multiple spaces or invalid separator")
        val = group_value(g)
        if val <= 0:
            raise ValueError("Group must have positive nesting depth")
        result.append(val)
    return result
